// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MY_BANK} from "../src/MY_BANK.sol";

contract InvMutTest is Test {
    MY_BANK c;
    function setUp() public { c = new MY_BANK(address(this)); }

    function testFuzz_property(address actor, uint256 amount, uint256 unlockTime) public {
        amount = bound(amount, 0, 10 ether);
        vm.deal(actor, amount);

        uint256 initLen = _historyLengthProbe(100);

        vm.prank(actor);
        bool ok;
        try c.Put{value: amount}(unlockTime) {
            ok = true;
        } catch {
            ok = false;
        }

        uint256 newLen = _historyLengthProbe(100);

        if (amount > 0 && ok) {
            assertTrue(newLen == initLen + 1);
        } else {
            assertTrue(newLen == initLen || newLen == initLen + 1);
        }
    }

    function _historyLengthProbe(uint256 cap) internal returns (uint256) {
        uint256 cnt = 0;
        for (uint256 i = 0; i < cap; i++) {
            (bool s, ) = address(this).staticcall(abi.encodeWithSignature("History(uint256)", i));
            if (s) cnt++; else break;
        }
        return cnt;
    }
}
